from pathlib import Path
from PIL import Image, ImageOps
import html, re

ROOT=Path(__file__).resolve().parent
DIST=ROOT/'dist'
for n in range(1,25):
    source=ROOT.parent/f'images/image{n}.jpeg' if n<=22 else ROOT/f'inspiration/{n}.png'
    im=ImageOps.exif_transpose(Image.open(source)).convert('RGB')
    im.thumbnail((1440,1600))
    im.save(DIST/f'assets/image{n}.webp','WEBP',quality=89)
    for width in (480,900):
        variant=im.copy()
        variant.thumbnail((width,round(width*im.height/im.width)))
        variant.save(DIST/f'assets/image{n}-{width}.webp','WEBP',quality=83)
